        },
        email: {
          label: "Email address",
          type: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        phone: {
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          helperText: "Optional. Use a format like (555) 123-4567 or +1 555 123 4567."
        }
      };

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function validateField(name, value) {
        const trimmedValue = value.trim();

        if (name === "fullName" && !trimmedValue) {
          return "Full name is required.";
        }

        if (name === "email") {
          if (!trimmedValue) {
            return "Email address is required.";
          }

          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
        }

        if (name === "phone" && trimmedValue && !phonePattern.test(trimmedValue)) {
          return "Enter a valid phone number using digits, spaces, parentheses, or dashes.";
        }

        return "";
      }

      function FormField(name, config) {
        const value = state.values[name];
        const error = state.errors[name];
        const helperId = config.helperText ? `${name}-helper` : "";
        const errorId = `${name}-error`;
        const describedBy = [helperId, errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${name}">${config.label}${config.required ? " *" : ""}</label>
            <input
              id="${name}"
              name="${name}"
              type="${config.type}"
              placeholder="${config.placeholder}"
              value="${escapeHtml(value)}"
              ${config.required ? "required" : ""}
              aria-invalid="${error ? "true" : "false"}"
              aria-describedby="${describedBy}"
            />
            ${
              config.helperText
                ? `<p class="helper-text" id="${helperId}">${config.helperText}</p>`
                : ""
            }
            <p class="validation-message" id="${errorId}" role="alert">${error}</p>
          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <form id="support-contact-form" novalidate>
            ${Object.entries(fieldConfig)
              .map(([name, config]) => FormField(name, config))
              .join("")}
            <button class="submit-button" type="submit">Submit request</button>
            ${state.successMessage ? `<p class="success-message">${state.successMessage}</p>` : ""}
          </form>
        `;
      }

      function App() {
        return `
          <main class="page-shell">
            <section class="support-card" aria-labelledby="support-heading">
              <div class="card-header">
                <p class="eyebrow">Support</p>
                <h1 id="support-heading">Get in touch with our team</h1>
                <p class="intro">
                  Share your details below and we will follow up as soon as possible.
                </p>
              </div>
              <div class="card-body">
                ${SupportContactForm()}
              </div>
            </section>
          </main>
        `;
      }

      function render() {
        root.innerHTML = App();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-contact-form");

        form.addEventListener("input", (event) => {
          const { name, value } = event.target;

          if (!Object.hasOwn(state.values, name)) {
            return;
          }

          state.values[name] = value;
          state.errors[name] = validateField(name, value);
          state.successMessage = "";
          render();
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          state.errors = Object.keys(state.values).reduce((errors, name) => {
            errors[name] = validateField(name, state.values[name]);
            return errors;
          }, {});

          const hasErrors = Object.values(state.errors).some(Boolean);

          if (hasErrors) {
            state.successMessage = "";
            render();
            return;
          }

          state.successMessage = "Thanks! Your support request is ready to be reviewed.";
          render();
        });
      }

      render();
    </script>
